```js
// Resolves the ball against every brick it overlaps: breaks, scores, bounces
// and pushes the ball back out of the brick.
function resolveBricks(state) {
  const { ball } = state;
  const r = ball.r;
  let hit = null;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (!collides(ball, brick)) continue;
    // Face vs corner: the axis of the smallest penetration is the hit face;
    // equal penetrations mean a corner hit (both axes bounce).
    const penX = Math.min(ball.x + r - brick.x, brick.x + brick.w - (ball.x - r));
    const penY = Math.min(ball.y + r - brick.y, brick.y + brick.h - (ball.y - r));
    let face;
    if (penX < penY) face = 'x';
    else if (penY < penX) face = 'y';
    else face = 'corner';
    if (hit === null) hit = { brick, face };
  }
  if (hit === null) return;
  const { brick, face } = hit;
  if (face === 'x') {
    const fromLeft = ball.x + r - brick.x <= brick.x + brick.w - (ball.x - r);
    if (fromLeft) ball.x = brick.x - r; else ball.x = brick.x + brick.w + r;
    ball.vx = -ball.vx;
  } else if (face === 'y') {
    const fromTop = ball.y + r - brick.y <= brick.y + brick.h - (ball.y - r);
    if (fromTop) ball.y = brick.y - r; else ball.y = brick.y + brick.h + r;
    ball.vy = -ball.vy;
  } else {
    // corner: push out to the nearest corner, bounce both axes
    ...
  }
  // break + score every brick the ball still overlaps
  for (const b of state.bricks) {
    if (!b.alive) continue;
    if (collides(ball, b)) {
      b.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(b, state.combo);
    }
  }
}
```

