// --- Brick collision (tested through `step`) -------------------------------

// Resolves the ball against the bricks it overlaps at its current position:
// breaks the hit brick, bounces it off the hit face and pushes it back out.
// Face vs corner: the hit axis is the one with the smallest penetration; equal
// penetrations mean the ball is on a corner and BOTH axes bounce. The brick is
// broken, and so is every brick the ball still overlaps once repositioned.
function resolveBricks(state) {
  const { ball } = state;
  const r = ball.r;

  let hit = null; // { brick, face: 'x' | 'y' | 'corner' }
  for (const brick of state.bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;
    const penX = Math.min(ball.x + r - brick.x, brick.x + brick.w - (ball.x - r));
    const penY = Math.min(ball.y + r - brick.y, brick.y + brick.h - (ball.y - r));
    let face;
    if (penX < penY) face = 'x';
    else if (penY < penX) face = 'y';
    else face = 'corner';
    if (hit === null) hit = { brick, face };
  }
  if (hit === null) return;

  const { brick, face } = hit;
  if (face === 'x') {
    const fromLeft = ball.x + r - brick.x <= brick.x + brick.w - (ball.x - r);
    ball.x = fromLeft ? brick.x - r : brick.x + brick.w + r;
    ball.vx = -ball.vx;
  } else if (face === 'y') {
    const fromTop = ball.y + r - brick.y <= brick.y + brick.h - (ball.y - r);
    ball.y = fromTop ? brick.y - r : brick.y + brick.h + r;
    ball.vy = -ball.vy;
  } else {
    // Corner: push the ball out to the nearest corner, bounce both axes.
    const fromLeft = ball.x + r - brick.x <= brick.x + brick.w - (ball.x - r);
    const fromTop = ball.y + r - brick.y <= brick.y + brick.h - (ball.y - r);
    ball.x = fromLeft ? brick.x - r : brick.x + brick.w + r;
    ball.y = fromTop ? brick.y - r : brick.y + brick.h + r;
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }

  for (const b of state.bricks) {
    if (!b.alive || !collides(ball, b)) continue;
    b.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(b, state.combo);
  }
}

