// --- Brick collision (tested through `step`) -------------------------------

// Resolves the ball against the brick it overlaps: breaks it, bounces it off
// the hit face and pushes it back out. When the ball already overlapped a
// brick at the START of the step, the overlap is resolved from that position
// (the most recent penetration); otherwise from the current position.
// Face vs corner: the hit axis is the one with the smallest penetration; equal
// penetrations mean the ball is on a corner and BOTH axes bounce. Every brick
// the ball still overlaps once repositioned breaks and scores.
function resolveBricks(state, prevX, prevY) {
  const { ball } = state;
  const r = ball.r;

  // Prefer the pre-step position when the ball already overlapped a brick.
  const atPrev = state.bricks.some((b) => b.alive && collidesAt(ball, b, prevX, prevY));
  const bx = atPrev ? prevX : ball.x;
  const by = atPrev ? prevY : ball.y;

  let hit = null; // { brick, face: 'x' | 'y' | 'corner' }
  for (const brick of state.bricks) {
    if (!brick.alive || !collidesAt(ball, brick, bx, by)) continue;
    const penX = Math.min(bx + r - brick.x, brick.x + brick.w - (bx - r));
    const penY = Math.min(by + r - brick.y, brick.y + brick.h - (by - r));
    let face;
    if (penX < penY) face = 'x';
    else if (penY < penX) face = 'y';
    else face = 'corner';
    if (hit === null) hit = { brick, face };
  }
  if (hit === null) return;

  const { brick, face } = hit;
  if (face === 'x') {
    const fromLeft = bx + r - brick.x <= brick.x + brick.w - (bx - r);
    ball.x = fromLeft ? brick.x - r : brick.x + brick.w + r;
    ball.vx = -ball.vx;
  } else if (face === 'y') {
    const fromTop = by + r - brick.y <= brick.y + brick.h - (by - r);
    ball.y = fromTop ? brick.y - r : brick.y + brick.h + r;
    ball.vy = -ball.vy;
  } else {
    // Corner: push the ball out to the nearest corner, bounce both axes.
    const fromLeft = bx + r - brick.x <= brick.x + brick.w - (bx - r);
    const fromTop = by + r - brick.y <= brick.y + brick.h - (by - r);
    ball.x = fromLeft ? brick.x - r : brick.x + brick.w + r;
    ball.y = fromTop ? brick.y - r : brick.y + brick.h + r;
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }

  // The hit brick always breaks (it was touched), then every brick the ball
  // still overlaps once repositioned.
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
  for (const b of state.bricks) {
    if (!b.alive || !collides(ball, b)) continue;
    b.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(b, state.combo);
  }
}

// collides() at an arbitrary position (the ball is not moved yet).
function collidesAt(ball, brick, x, y) {
  return (
    x + ball.r > brick.x &&
    x - ball.r < brick.x + brick.w &&
    y + ball.r > brick.y &&
    y - ball.r < brick.y + brick.h
  );
}

