Hmm — la structure actuelle a `resolveAt` inline avec les pénétrations (bx, by). Je vais refactorer : une fonction `resolveAt(state, brick, x, y)` qui calcule la face par pénétration à (x, y), pousse et flip. Et pour le cas tEnter ≥ 0 : le point d'entrée + face par plaques, puis flip.

Hmm — le flip et la poussée : pour le cas plaques, la position est DÉJÀ le point d'entrée (pas de poussée nécessaire — la balle touche juste la face). Donc flip seulement. Pour le cas pénétration : poussée + flip.

Le kill final (commun) : brique résolue + chevauchées à la position finale.

Écrivons ça proprement :

```js
function resolveBricks(state, prevX, prevY) {
  const { ball } = state;
  const r = ball.r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  // Balayage du segment [pré → post] contre le pavé étendu de chaque brique :
  // temps d'entrée/sortie par plaque (slab method). Le premier contact (plus
  // petit tEnter) est le seul résolu : un rebond par passe et par axe.
  let best = null;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const xmin = brick.x - r, xmax = brick.x + brick.w + r;
    const ymin = brick.y - r, ymax = brick.y + brick.h + r;
    let txEnter, txExit;
    if (dx === 0) {
      if (prevX < xmin || prevX > xmax) continue;
      txEnter = -Infinity; txExit = Infinity;
    } else {
      const t1 = (xmin - prevX) / dx, t2 = (xmax - prevX) / dx;
      txEnter = Math.min(t1, t2); txExit = Math.max(t1, t2);
    }
    let tyEnter, tyExit;
    if (dy === 0) {
      if (prevY < ymin || prevY > ymax) continue;
      tyEnter = -Infinity; tyExit = Infinity;
    } else {
      const t1 = (ymin - prevY) / dy, t2 = (ymax - prevY) / dy;
      tyEnter = Math.min(t1, t2); tyExit = Math.max(t1, t2);
    }
    const tEnter = Math.max(txEnter, tyEnter);
    const tExit = Math.min(txExit, tyExit);
    if (tEnter > tExit || tEnter > 1 || tExit < 0) continue;
    if (best === null || tEnter < best.tEnter) best = { brick, tEnter, txEnter, tyEnter };
  }
  if (best === null) return;

  const { brick, tEnter, txEnter, tyEnter } = best;
  if (tEnter < 0) {
    // Chevauchement dès le début du pas : la face est celle de la plus petite
    // pénétration, mesurée à la position initiale.
    const bx = prevX, by = prevY;
    const penX = Math.min(bx + r - brick.x, brick.x + brick.w - (bx - r));
    const penY = Math.min(by + r - brick.y, brick.y + brick.h - (by - r));
    let face;
    if (penX < penY) face = 'x';
    else if (penY < penX) face = 'y';
    else face = 'corner';
    pushOut(state, brick, face, bx, by);
  } else {
    // Franchissement pendant le pas : la balle s'arrête au point de contact et
    // rebondit sur la plaque franchie en dernier.
    ball.x = prevX + dx * tEnter;
    ball.y = prevY + dy * tEnter;
    let face;
    if (txEnter > tyEnter) face = 'x';
    else if (tyEnter > txEnter) face = 'y';
    else face = 'corner';
    flip(state, face);
  }

  // La brique touchée casse toujours, puis chaque brique encore chevauchée.
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
  for (const b of state.bricks) {
    if (!b.alive || !collides(ball, b)) continue;
    b.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(b, state.combo);
  }
}

function pushOut(state, brick, face, x, y) {
  const { ball } = state;
  const r = ball.r;
  if (face === 'x') {
    const fromLeft = x + r - brick.x <= brick.x + brick.w - (x - r);
    ball.x = fromLeft ? brick.x - r : brick.x + brick.w + r;
    ball.vx = -ball.vx;
  } else if (face === 'y') {
    const fromTop = y + r - brick.y <= brick.y + brick.h - (y - r);
    ball.y = fromTop ? brick.y - r : brick.y + brick.h + r;
    ball.vy = -ball.vy;
  } else {
    const fromLeft = x + r - brick.x <= brick.x + brick.w - (x - r);
    const fromTop = y + r - brick.y <= brick.y + brick.h - (y - r);
    ball.x = fromLeft ? brick.x - r : brick.x + brick.w + r;
    ball.y = fromTop ? brick.y - r : brick.y + brick.h + r;
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}

function flip(state, face) {
  const { ball } = state;
  if (face === 'x') ball.vx = -ball.vx;
  else if (face === 'y') ball.vy = -ball.vy;
  else { ball.vx = -ball.vx; ball.vy = -ball.vy; }
}
