// --- Brick collision (tested through `step`) -------------------------------

// Resolves the ball against the bricks, sweeping the segment the ball covered
// during the step (prevX, prevY) -> (ball.x, ball.y). Each brick is tested as
// its AABB expanded by the ball radius; the slab method gives the entry/exit
// times of the segment into that expanded box. The EARLIEST contact (smallest
// entry time) is the only one resolved — one bounce per pass and per axis, so
// a ball straddling a grid seam never double-flips. A contact already started
// at the beginning of the step (negative entry time) is resolved from the
// pre-step position by penetration; a crossing during the step stops the ball
// at the entry point and bounces it off the slab entered last (the hit face).
function resolveBricks(state, prevX, prevY) {
  const { ball } = state;
  const r = ball.r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let best = null; // { brick, tEnter, txEnter, tyEnter }
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const xmin = brick.x - r;
    const xmax = brick.x + brick.w + r;
    const ymin = brick.y - r;
    const ymax = brick.y + brick.h + r;

    let txEnter;
    let txExit;
    if (dx === 0) {
      if (prevX < xmin || prevX > xmax) continue;
      txEnter = -Infinity;
      txExit = Infinity;
    } else {
      const t1 = (xmin - prevX) / dx;
      const t2 = (xmax - prevX) / dx;
      txEnter = Math.min(t1, t2);
      txExit = Math.max(t1, t2);
    }
    let tyEnter;
    let tyExit;
    if (dy === 0) {
      if (prevY < ymin || prevY > ymax) continue;
      tyEnter = -Infinity;
      tyExit = Infinity;
    } else {
      const t1 = (ymin - prevY) / dy;
      const t2 = (ymax - prevY) / dy;
      tyEnter = Math.min(t1, t2);
      tyExit = Math.max(t1, t2);
