// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const px = ball.x;
  const py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle — swept test: the ball's bottom must cross the paddle band during
  // the step (a 12 px band can be jumped in a single 13 px step at level 1),
  // but a ball already below the paddle keeps falling.
  if (
    ball.vy > 0 &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w &&
    py + ball.r <= paddle.y + paddle.h &&
    ball.y + ball.r >= paddle.y
  ) {
    ball.y = paddle.y - ball.r;
    // The rebound angle depends on where the paddle was hit, but a dead-center
    // contact must never leave a vertical trajectory (angle mort): keep a
    // minimum horizontal component, preserving the incoming direction.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    const speed = ballSpeed(state.level);
    const vx = speed * 0.6 * (Math.abs(hit) < 0.1 ? (Math.sign(ball.vx) || 1) * 0.1 : hit);
    // Renormalize: the bounce keeps the level speed exactly (the old code
    // rewrote vx without touching vy, so the norm drifted with the hit spot).
    ball.vx = vx;
    ball.vy = -Math.sqrt(speed * speed - vx * vx);
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks: resolve the collision against the brick the ball overlaps, then
  // break and score every brick left overlapping the ball.
  resolveBricks(state, px, py);

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Brick collision (tested through `step`) -------------------------------

// Resolves the ball against the bricks, sweeping the segment the ball covered
// during the step (prevX, prevY) -> (ball.x, ball.y). Each brick is tested as
// its AABB expanded by the ball radius; the slab method gives the entry/exit
// times of the segment into that expanded box. The EARLIEST contact (smallest
// entry time) is the only one resolved — one bounce per pass and per axis, so
// a ball straddling a grid seam never double-flips. A contact already started
// at the beginning of the step (negative entry time) is resolved from the
// pre-step position by penetration; a crossing during the step stops the ball
// at the entry point and bounces it off the slab entered last (the hit face).
function resolveBricks(state, prevX, prevY) {
  const { ball } = state;
  const r = ball.r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let best = null; // { brick, tEnter, txEnter, tyEnter }
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const xmin = brick.x - r;
    const xmax = brick.x + brick.w + r;
    const ymin = brick.y - r;
    const ymax = brick.y + brick.h + r;

    let txEnter;
    let txExit;
    if (dx === 0) {
      if (prevX < xmin || prevX > xmax) continue;
      txEnter = -Infinity;
      txExit = Infinity;
    } else {
      const t1 = (xmin - prevX) / dx;
      const t2 = (xmax - prevX) / dx;
      txEnter = Math.min(t1, t2);
      txExit = Math.max(t1, t2);
    }
    let tyEnter;
    let tyExit;
    if (dy === 0) {
      if (prevY < ymin || prevY > ymax) continue;
      tyEnter = -Infinity;
      tyExit = Infinity;
    } else {
      const t1 = (ymin - prevY) / dy;
      const t2 = (ymax - prevY) / dy;
      tyEnter = Math.min(t1, t2);
      tyExit = Math.max(t1, t2);
    }

    const tEnter = Math.max(txEnter, tyEnter);
    const tExit = Math.min(txExit, tyExit);
    if (tEnter > tExit || tEnter > 1 || tExit < 0) continue;
    if (best === null || tEnter < best.tEnter) best = { brick, tEnter, txEnter, tyEnter };
  }
  if (best === null) return;

  const { brick, tEnter, txEnter, tyEnter } = best;
  if (tEnter < 0) {
    // Overlap already present at the start of the step: resolve from the
    // pre-step position, bouncing off the axis of smallest penetration.
    const penX = Math.min(prevX + r - brick.x, brick.x + brick.w - (prevX - r));
    const penY = Math.min(prevY + r - brick.y, brick.y + brick.h - (prevY - r));
    let face;
    if (penX < penY) face = 'x';
    else if (penY < penX) face = 'y';
    else face = 'corner';
    pushOut(ball, brick, face, prevX, prevY);
  } else {
    // Crossing during the step: stop at the entry point, bounce off the slab
    // entered last (the face that was hit).
    ball.x = prevX + dx * tEnter;
    ball.y = prevY + dy * tEnter;
    let face;
    if (txEnter > tyEnter) face = 'x';
    else if (tyEnter > txEnter) face = 'y';
    else face = 'corner';
    flip(ball, face);
  }

  // The hit brick always breaks (it was touched), then every brick the ball
  // still overlaps once repositioned.
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
  for (const b of state.bricks) {
    if (!b.alive || !collides(ball, b)) continue;
    b.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(b, state.combo);
  }
}

// Pushes the ball back out of the brick through the face it came from,
// measured at the overlap position (x, y), and bounces the matching axis.
function pushOut(ball, brick, face, x, y) {
  const r = ball.r;
  if (face === 'x') {
    const fromLeft = x + r - brick.x <= brick.x + brick.w - (x - r);
    ball.x = fromLeft ? brick.x - r : brick.x + brick.w + r;
    ball.vx = -ball.vx;
  } else if (face === 'y') {
    const fromTop = y + r - brick.y <= brick.y + brick.h - (y - r);
    ball.y = fromTop ? brick.y - r : brick.y + brick.h + r;
    ball.vy = -ball.vy;
  } else {
    const fromLeft = x + r - brick.x <= brick.x + brick.w - (x - r);
    const fromTop = y + r - brick.y <= brick.y + brick.h - (y - r);
    ball.x = fromLeft ? brick.x - r : brick.x + brick.w + r;
    ball.y = fromTop ? brick.y - r : brick.y + brick.h + r;
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}

// Reverses the velocity of the hit face ('x', 'y' or both for a corner).
function flip(ball, face) {
  if (face === 'x') {
    ball.vx = -ball.vx;
  } else if (face === 'y') {
    ball.vy = -ball.vy;
  } else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}

// --- Rendering (DOM): brick collision logic STILL mixed in here ------------

// Main render loop. For each live brick we test collision AND draw in the same
// pass: this is where logic and rendering are entangled.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: pure rendering now. Collision, scoring and bounces live in `step`.
  for (const brick of state.bricks) {
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();


