// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  ballSpeed,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  BALL_R,
  UP,
  DOWN,
  LEFT,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

// D1 — la balle qui frappe une brique doit rebondir (pas seulement la casser).
test('D1: une balle qui approche une brique par le bas rebondit sur sa face basse', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 4 && b.x === 244);
  state.ball = { x: 300, y: brick.y + brick.h + BALL_R, r: BALL_R, vx: 0, vy: -ballSpeed(1) };
  step(state, 0.05);
  assert.equal(brick.alive, false, 'la brique doit casser');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'la balle doit repartir vers le bas');
});

// D2 — l'axe inversé est celui de la face touchée (jamais « toujours vy »).
test('D2: un choc latéral inverse vx et pas vy', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 4 && b.x === 244);
  // Dans cette grille dense (gap 8 px < diamètre 14 px), la balle entre deux
  // colonnes chevauche toujours la brique précédente : la face la plus pénétrée
  // est x, donc vx s'inverse et vy reste inchangé.
  state.ball = { x: brick.x - BALL_R - 1, y: brick.y + 10, r: BALL_R, vx: 300, vy: 50 };
  step(state, 0.05);
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vx), LEFT, 'vx doit s inverser');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'vy doit rester inchangé');
});

test('D2: un choc sur le coin inverse les deux axes', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 4 && b.x === 4);
  // Sur une brique intérieure, les pavés étendus des colonnes voisines se
  // chevauchent (gap 8 px < diamètre 14 px) : le coin n'y est pas déterministe.
  // La col 0 a son coin bas-gauche dégagé : la balle vise pile ce coin, les
  // deux plaques sont franchies au même instant -> coin, les deux axes s'inversent.
  state.ball = { x: brick.x - BALL_R - 5, y: brick.y + brick.h + BALL_R + 5, r: BALL_R, vx: 300, vy: -300 };
  step(state, 0.05);
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vx), LEFT, 'vx doit s inverser');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'vy doit s inverser');
});

// D3 — après un rebond, la balle est poussée hors de la brique (pas de collant).
test('D3: après un rebond, la balle est poussée hors de la brique', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 4 && b.x === 244);
  state.ball = { x: 300, y: brick.y + 14, r: BALL_R, vx: 0, vy: -ballSpeed(1) };
  step(state, 0.05);
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vy), DOWN);
  assert.ok(state.ball.y - state.ball.r >= brick.y + brick.h - 1e-6, 'balle entièrement sous la brique');
});

// D4 — une balle à cheval sur une couture (gap 8 px < diamètre 14 px) ne doit
// subir qu'UN seul rebond : deux inversions s'annuleraient et elle traverserait.
test('D4: une balle à cheval sur une couture ne rebondit qu une fois', () => {
  const state = createState(1);
  const top = state.bricks.find((b) => b.row === 3 && b.x === 244);
  const bottom = state.bricks.find((b) => b.row === 4 && b.x === 244);
  state.ball = { x: 300, y: 156, r: BALL_R, vx: 0, vy: -ballSpeed(1) };
  step(state, 0.05);
  assert.equal(top.alive, false, 'la brique haute doit casser');
  assert.equal(bottom.alive, false, 'la brique basse doit casser');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'un seul rebond vertical');
});

// D5 — tunneling : au niveau 6, le pas max (710 × 0.05 = 35,5 px) dépasse
// l'épaisseur d'une brique + le diamètre de la balle (20 + 14 = 34 px) : la
// détection discrète ne voit aucun chevauchement, il faut balayer le segment.
test('D5: un pas plus long que la brique balaye la traversée et rebondit', () => {
  const state = createState(6);
  const brick = state.bricks.find((b) => b.row === 4 && b.x === 244);
  const above = state.bricks.find((b) => b.row === 3 && b.x === 244);
  state.ball = { x: 300, y: brick.y + brick.h + BALL_R + 1, r: BALL_R, vx: 0, vy: -ballSpeed(6) };
  step(state, 0.05); // 35,5 px > 34 px (BRICK_H + 2*BALL_R)
  assert.equal(brick.alive, false, 'la brique doit casser malgré le saut');
  assert.equal(above.alive, true, 'la balle doit rebondir avant d atteindre la rangée au-dessus');
  assert.ok(Math.abs(state.ball.y - (brick.y + brick.h + BALL_R)) < 1e-6, 'arrêtée au contact de la face basse');
  assert.equal(Math.sign(state.ball.vy), DOWN);
});

// D6 — le paddle : au niveau 1 le pas max (13 px) dépasse déjà la bande du
// paddle (12 px). Le test doit balayer le segment, pas la position finale :
// une balle rapide rebondit, une balle déjà passée sous le paddle tombe.
test('D6: une balle rapide ne saute pas la bande du paddle; déjà passée, elle tombe', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 440.5, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 0.05); // bas de balle 447,5 -> 460,5 : saute la bande [448, 460]
  assert.equal(Math.sign(state.ball.vy), UP, 'doit rebondir sur le paddle');
  assert.equal(state.ball.y, 448 - BALL_R, 'repositionnée au-dessus du paddle');

  const falling = createState(1);
  falling.ball = { x: 320, y: 462, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(falling, 0.05); // bas déjà à 469 > 460
  assert.equal(Math.sign(falling.ball.vy), DOWN, 'déjà passée: pas de rebond');
});

// D7 — angle mort : un contact au centre exact du paddle (hit = 0) donnerait
// vx = 0 et une trajectoire verticale en boucle : il faut une composante
// horizontale minimale.
test('D7: un contact au centre exact du paddle ne donne jamais vx = 0', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 450, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 0.05);
  assert.equal(Math.sign(state.ball.vy), UP, 'remonte');
  assert.ok(Math.abs(state.ball.vx) > 0, 'une composante horizontale est conservée');
});

// D8 — la norme après un rebond de paddle doit être exactement ballSpeed(niveau)
// (le rebond réécrit vx sans renormaliser, la vitesse dériverait avec hit).
test('D8: un rebond de paddle conserve la vitesse du niveau', () => {
  const state = createState(1);
  state.ball = { x: 360, y: 450, r: BALL_R, vx: 100, vy: ballSpeed(1) };
  step(state, 0.05);
  const speed = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(speed - ballSpeed(1)) < 1e-6, `vitesse ${speed} doit être ${ballSpeed(1)}`);
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// TODO (#5): test comboMultiplier / scoreForBrick.
// TODO      : test level progression and loadBest/saveBest persistence.

