test('D1: a ball approaching a brick from below bounces off its bottom face', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 4 && b.x === 244);
  state.ball = { x: 300, y: brick.y + brick.h + BALL_R, r: BALL_R, vx: 0, vy: -ballSpeed(1) };
  step(state, 0.05);
  assert.equal(brick.alive, false, 'the brick must break');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'the ball must bounce back down');
});

// D2 — the flipped axis is the axis of the hit face (never "always vy").
test('D2: a side hit flips vx and not vy', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 4 && b.x === 244);
  // In this dense grid (8 px gap < 14 px diameter) a ball between two columns
  // always overlaps the previous brick: the most penetrated face is x, so vx
  // flips and vy stays unchanged.
  state.ball = { x: brick.x - BALL_R - 1, y: brick.y + 10, r: BALL_R, vx: 300, vy: 50 };
  step(state, 0.05);
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vx), LEFT, 'vx must flip');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'vy must stay unchanged');
});

test('D2: a corner hit flips both axes', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 4 && b.x === 4);
  // On an inner brick the expanded boxes of neighbouring columns overlap
  // (8 px gap < 14 px diameter): the corner is not deterministic there. Column
  // 0 has a free bottom-left corner: the ball aims straight at it, both slabs
  // are crossed at the same instant -> corner, both axes flip.
  state.ball = { x: brick.x - BALL_R - 5, y: brick.y + brick.h + BALL_R + 5, r: BALL_R, vx: 300, vy: -300 };
  step(state, 0.05);
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vx), LEFT, 'vx must flip');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'vy must flip');
});

// D3 — after a bounce the ball is pushed out of the brick (no sticking).
test('D3: after a bounce the ball is pushed out of the brick', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 4 && b.x === 244);
  state.ball = { x: 300, y: brick.y + 14, r: BALL_R, vx: 0, vy: -ballSpeed(1) };
  step(state, 0.05);
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vy), DOWN);
  assert.ok(state.ball.y - state.ball.r >= brick.y + brick.h - 1e-6, 'the ball must end fully below the brick');
});

// D4 — a ball straddling a grid seam (8 px gap < 14 px diameter) must bounce
// exactly ONCE: two inversions would cancel and let it through.
test('D4: a ball straddling a grid seam bounces exactly once', () => {
  const state = createState(1);
  const top = state.bricks.find((b) => b.row === 3 && b.x === 244);
  const bottom = state.bricks.find((b) => b.row === 4 && b.x === 244);
  state.ball = { x: 300, y: 156, r: BALL_R, vx: 0, vy: -ballSpeed(1) };
  step(state, 0.05);
  assert.equal(top.alive, false, 'the top brick must break');
  assert.equal(bottom.alive, false, 'the bottom brick must break');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'exactly one vertical bounce');
});

// D5 — tunneling: at level 6 the max step (710 × 0.05 = 35.5 px) exceeds a
// brick's thickness + the ball diameter (20 + 14 = 34 px): discrete detection
// sees no overlap, the segment must be swept.
test('D5: a step longer than the brick sweeps the crossing and bounces', () => {
  const state = createState(6);
  const brick = state.bricks.find((b) => b.row === 4 && b.x === 244);
  const above = state.bricks.find((b) => b.row === 3 && b.x === 244);
  state.ball = { x: 300, y: brick.y + brick.h + BALL_R + 1, r: BALL_R, vx: 0, vy: -ballSpeed(6) };
  step(state, 0.05); // 35,5 px > 34 px (BRICK_H + 2*BALL_R)
  assert.equal(brick.alive, false, 'the brick must break despite the jump');
  assert.equal(above.alive, true, 'the ball must bounce before reaching the row above');
  assert.ok(Math.abs(state.ball.y - (brick.y + brick.h + BALL_R)) < 1e-6, 'stopped at the bottom face contact');
  assert.equal(Math.sign(state.ball.vy), DOWN);
});

// D6 — the paddle: at level 1 the max step (13 px) already exceeds the paddle
// band (12 px). The test must sweep the segment, not the final position: a
// fast ball bounces, a ball already below the paddle falls through.
test('D6: a fast ball cannot jump the paddle band; a ball below it falls through', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 440.5, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 0.05); // ball bottom 447.5 -> 460.5: jumps the band [448, 460]
  assert.equal(Math.sign(state.ball.vy), UP, 'must bounce off the paddle');
  assert.equal(state.ball.y, 448 - BALL_R, 'repositioned above the paddle');

  const falling = createState(1);
  falling.ball = { x: 320, y: 462, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(falling, 0.05); // bottom already at 469 > 460
  assert.equal(Math.sign(falling.ball.vy), DOWN, 'already past: no bounce');
});

// D7 — angle mort: a dead-center paddle contact (hit = 0) would give vx = 0
// and a looping vertical trajectory: a minimum horizontal component is kept.
test('D7: a dead-center paddle hit never leaves vx = 0', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 450, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 0.05);
  assert.equal(Math.sign(state.ball.vy), UP, 'bounces up');
  assert.ok(Math.abs(state.ball.vx) > 0, 'a horizontal component is kept');
});

// D8 — the norm after a paddle bounce must be exactly ballSpeed(level): the
// bounce rewrites vx without renormalizing, so the speed drifts with hit.
test('D8: a paddle rebound keeps the level speed', () => {
  const state = createState(1);
  state.ball = { x: 360, y: 450, r: BALL_R, vx: 100, vy: ballSpeed(1) };
  step(state, 0.05);
  const speed = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(speed - ballSpeed(1)) < 1e-6, `speed ${speed} must be ${ballSpeed(1)}`);
});

