    state.paddle.x = target;
    const lost = step(state, 1/60);
    if (lost) {
      lives -= 1;
      state.combo = 0;
      if (lives <= 0) break;
      state.ball = createState(level).ball;
    }
    if (state.bricks.every(b => !b.alive)) {
      level += 1;
      state.level = level;
      state.bricks = makeBricks(level);
      state.ball = createState(level).ball;
    }
    score = state.score;
    frames++;
  }
  console.log('frames:', frames, '| vies restantes:', lives, '| niveaux terminés:', level - 1);
  console.log('score final:', score);
  const alive = state.bricks.filter(b => b.alive).length;
  console.log('briques restantes au niveau', level, ':', alive, '/', state.bricks.length);
  console.log('balle:', state.ball.x.toFixed(0), state.ball.y.toFixed(0), '| |v|:', Math.hypot(state.ball.vx, state.ball.vy).toFixed(1), '(niveau', level, '=>', ballSpeed(level) + ')');
});
